@Test(arguments: chipFixtures) func replayChipInventory(f: ChipFixture) {
    let selection = SMCSensorSelection.select(inventory: f.inventory, chipName: f.chip)
    #expect(!selection.cpuKeys.isEmpty, "\(f.name) CPU")
    #expect(!selection.gpuKeys.isEmpty, "\(f.name) GPU")
    #expect(selection.cpuKeys.count >= 2 || selection.cpuSource == .fallback)
    #expect(selection.gpuKeys.count >= 2 || selection.gpuSource == .fallback)
    #expect(selection.cpuKeys.isSubset(of: f.inventory))
    #expect(selection.gpuKeys.isSubset(of: f.inventory))
    #expect(selection.cpuKeys.isDisjoint(with: f.forbiddenCPU.split(separator: " ").map(String.init)), "\(f.name) CPU misclassification")
    #expect(selection.gpuKeys.isDisjoint(with: f.forbiddenGPU.split(separator: " ").map(String.init)), "\(f.name) GPU misclassification")
}

@Test func familyFallbackIsIndependentAndRequiresTwoMappedProbes() {
    let inventory: Set<String> = ["Te05", "TpZZ", "TpYY", "Tg00", "Tg01"]
    let s = SMCSensorSelection.select(inventory: inventory, chipName: "Apple M3 Pro")
    #expect(s.cpuSource == .fallback)
    #expect(s.cpuKeys == ["TpZZ", "TpYY", "Te05"])
    #expect(s.gpuSource == .chipMap)
    let two = SMCSensorSelection.select(inventory: inventory.union(["Te0S"]), chipName: "Apple M3 Pro")
    #expect(two.cpuSource == .chipMap)
    #expect(two.cpuKeys == ["Te05", "Te0S"])
    let zero = SMCSensorSelection.select(inventory: [], chipName: "Apple M3 Pro")
    #expect(zero.cpuSource == .fallback && zero.gpuSource == .fallback)
    #expect(zero.cpuKeys.isEmpty && zero.gpuKeys.isEmpty)
    let oneGPU = SMCSensorSelection.select(inventory: ["Tp00", "Tp04", "Tg00"], chipName: "Apple M5 Max")
    #expect(oneGPU.cpuSource == .chipMap && oneGPU.gpuSource == .fallback)
    #expect(oneGPU.gpuKeys == ["Tg00"])
}

@Test func chipNameTokensDoNotConflateGenerationsOrVariants() {
    let keys: Set<String> = ["Te05", "Te0S", "TpZZ", "TpYY", "Tg00", "Tg01"]
    #expect(SMCSensorSelection.select(inventory: keys, chipName: "Apple M4 Pro").cpuSource == .chipMap)
    for name in ["Apple M10", "Apple M7", "Apple M4 Mystery", "Apple M4 Ultra", "Apple M3 Pro extra", ""] {
        let s = SMCSensorSelection.select(inventory: keys, chipName: name)
        #expect(s.cpuSource == .fallback && s.gpuSource == .fallback)
        #expect(s.cpuKeys == ["TpZZ", "TpYY", "Te05", "Te0S"])
    }
}
